(function () {
  const questions = [
    ['周末休息，你更倾向？', ['约朋友出门逛街聚会', '一半社交一半独处', '自己宅家，不被打扰']],
    ['遇到烦心事，你会？', ['立刻找人倾诉吐槽', '先自己消化，必要时再说', '习惯自己扛，很少跟别人讲']],
    ['做计划的时候，你更喜欢？', ['随性走，走一步看一步', '价值相等大致有个框架，允许临时变动', '提前安排好所有细节']],
    ['此时此刻有两件价值相等物品可以拿走，你更偏向？', ['可爱的头戴耳机', '好看的化妆品套装']],
    ['别人对你提出不同意见，你的第一反应？', ['会有点不舒服，但愿意沟通', '冷静听完，再判断对错', '内心会思考，但不会轻易表露情绪']],
    ['此时此刻有三件价值相等物品可以拿走，你更偏向？', ['漂亮的新鞋子', '好闻的香水', '好看的新衣服']],
    ['面对新的陌生环境，你会？', ['很快主动搭话，快速融入', '慢慢观察，熟悉之后放开', '保持距离，先观察再接触']],
    ['如果可以随便选，你更偏爱实物礼物，还是体验类礼物（约会、旅行、手工体验）？', ['实物，拿到手里很有幸福感', '体验类，一起经历的回忆更重要', '两者都可以，看心意']],
    ['当你要做一个重要决定，你习惯？', ['快速下定决心，不纠结', '多方打听参考别人建议再定', '反复权衡，想很久才做选择']],
    ['下面哪一类小东西，会让你觉得很开心？', ['饰品（项链、手链、耳钉）', '香薰、蜡烛、氛围感摆件', '毛绒玩偶、可爱周边', '美妆护肤（口红、香水）', '书籍/手办']],
    ['朋友向你倾诉难过的事，你第一反应是？', ['帮她想解决办法，出主意', '共情安慰，先陪着情绪', '静静倾听，不多发表看法']],
    ['你平时会有“很想要，但一直没舍得买”的东西吗？', ['有，会偶尔念叨', '有，但不会经常说', '基本没有']],
    ['朋友向你倾诉难过的事，你第一反应是？', ['帮她想解决办法，出主意', '共情安慰，先陪着情绪', '静静倾听，不多发表看法']],
    ['计划被临时打乱，你的感受是？', ['无所谓，随机应变也挺好', '有点烦躁，但可以接受调整', '会很不舒服，希望一切按计划走']],
    ['空闲时间，你更愿意？', ['找人一起玩，热热闹闹', '一部分社交一部分自己待着', '独自享受安静时光']],
    ['别人夸奖你的时候，你会？', ['开心坦然接受', '有点不好意思，谦虚推脱', '内心会思考对方是不是真心']],
    ['发生矛盾争吵，你倾向？', ['当场把话说开，尽快解决', '先冷静一会，之后再沟通', '尽量回避冲突，不想吵架']],
    ['面对全新的任务，你的心态？', ['很兴奋，想立刻尝试', '有点好奇，但需要先了解清楚', '会有压力，担心做不好']],
    ['对于别人的小缺点，你会？', ['会直接指出来', '心里清楚，但不会多说', '包容，不太在意细枝末节']],
    ['遇到压力大的时候，你会？', ['找人吐槽释放情绪', '做点爱好的事转移注意力', '自己默默消化，不向外流露']]
  ];

  const form = document.getElementById('questionnaire-form');
  const list = document.getElementById('questionnaire-list');
  const count = document.getElementById('questionnaire-count');
  const resultCount = document.getElementById('questionnaire-result-count');
  const progressBar = document.getElementById('questionnaire-progress-bar');
  const progressTrack = document.querySelector('.questionnaire-progress-track');
  const result = document.getElementById('questionnaire-result');
  const summary = document.getElementById('questionnaire-summary');
  const error = document.getElementById('questionnaire-error');
  const reset = document.getElementById('questionnaire-reset');
  const submit = form.querySelector('.questionnaire-button-primary');
  const questionnaireApiUrl = 'http://127.0.0.1:8080/api/questionnaire';

  questions.forEach(function (question, questionIndex) {
    const fieldset = document.createElement('fieldset');
    fieldset.className = 'questionnaire-question';
    fieldset.dataset.question = String(questionIndex + 1);

    const legend = document.createElement('legend');
    const number = document.createElement('span');
    number.className = 'questionnaire-number';
    number.textContent = String(questionIndex + 1).padStart(2, '0');
    legend.append(number, document.createTextNode(question[0]));
    fieldset.appendChild(legend);

    const options = document.createElement('div');
    options.className = 'questionnaire-options';
    question[1].forEach(function (option, optionIndex) {
      const label = document.createElement('label');
      label.className = 'questionnaire-option';

      const input = document.createElement('input');
      input.type = 'radio';
      input.name = 'question-' + (questionIndex + 1);
      input.value = option;
      input.dataset.answer = String.fromCharCode(65 + optionIndex);
      input.dataset.question = String(questionIndex + 1);

      const marker = document.createElement('span');
      marker.className = 'questionnaire-option-marker';
      marker.textContent = String.fromCharCode(65 + optionIndex);

      const text = document.createElement('span');
      text.className = 'questionnaire-option-text';
      text.textContent = option;

      label.append(input, marker, text);
      options.appendChild(label);
      input.addEventListener('change', updateProgress);
    });

    fieldset.appendChild(options);
    list.appendChild(fieldset);
  });

  function getAnsweredCount() {
    return questions.reduce(function (answered, _, index) {
      return answered + (form.querySelector('input[name="question-' + (index + 1) + '"]:checked') ? 1 : 0);
    }, 0);
  }

  function updateProgress() {
    const answered = getAnsweredCount();
    count.textContent = String(answered);
    resultCount.textContent = String(answered);
    progressBar.style.width = (answered / questions.length) * 100 + '%';
    progressTrack.setAttribute('aria-valuenow', String(answered));
  }

  function clearError() {
    error.hidden = true;
    list.querySelectorAll('.questionnaire-question').forEach(function (fieldset) {
      fieldset.classList.remove('questionnaire-question-error');
    });
  }

  form.addEventListener('submit', async function (event) {
    event.preventDefault();
    clearError();

    const unanswered = questions.findIndex(function (_, index) {
      return !form.querySelector('input[name="question-' + (index + 1) + '"]:checked');
    });

    if (unanswered !== -1) {
      const fieldset = list.querySelector('[data-question="' + (unanswered + 1) + '"]');
      fieldset.classList.add('questionnaire-question-error');
      error.hidden = false;
      fieldset.scrollIntoView({ behavior: 'smooth', block: 'center' });
      fieldset.querySelector('input').focus({ preventScroll: true });
      return;
    }

    submit.disabled = true;
    submit.textContent = '正在提交...';

    const payload = new URLSearchParams();
    questions.forEach(function (_, index) {
      const selected = form.querySelector('input[name="question-' + (index + 1) + '"]:checked');
      payload.set('q' + (index + 1), selected.dataset.answer);
    });

    try {
      const response = await fetch(questionnaireApiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded'
        },
        body: payload.toString()
      });

      if (!response.ok) {
        throw new Error('request_failed');
      }
    } catch (requestError) {
      error.textContent = '提交失败，请检查服务器是否运行，然后重试。';
      error.hidden = false;
      submit.disabled = false;
      submit.textContent = '查看结果';
      return;
    }

    summary.replaceChildren();
    questions.forEach(function (_, index) {
      const selected = form.querySelector('input[name="question-' + (index + 1) + '"]:checked');
      const item = document.createElement('li');
      item.textContent = selected.value;
      summary.appendChild(item);
    });
    result.hidden = false;
    result.scrollIntoView({ behavior: 'smooth', block: 'start' });
    submit.disabled = false;
    submit.textContent = '已提交';
  });

  reset.addEventListener('click', function () {
    form.reset();
    clearError();
    result.hidden = true;
    summary.replaceChildren();
    submit.disabled = false;
    submit.textContent = '查看结果';
    updateProgress();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  updateProgress();
})();

