Tree) &#123;            //保存            s.push(pTree);            //处理左            pTree = pTree-&gt;pLeft;        &#125;        if (s.empty()) &#123;            break;        &#125;        //栈顶元素右侧        if (s.top()-&gt;pRight == NULL || s.top()-&gt;pRight == pMark) &#123;            //弹出            pMark = s.top();            s.pop();            printf(&quot;%d &quot;,pMark-&gt;nValue);        &#125;        else &#123;            pTree = s.top()-&gt;pRight;        &#125;    &#125;    cout &lt;&lt; endl;&#125;

